(ns episodes.migrate-session-spec
  (:require [speclj.core :refer :all]
            [gherclj.core :as g]
            [gherclj.lifecycle :as lifecycle]
            [isaac.config.config-steps :as config-steps]
            [isaac.episodes.episode-steps :as episode-steps]
            [isaac.foundation.cli-steps :as cli-steps]
            [isaac.foundation.fs-steps :as fs-steps]
            [isaac.foundation.root-steps :as root-steps]
            [isaac.session.session-steps :as session-steps]))

(describe "Episodes — migrate-session"

  (around [it]
    (binding [g/*state* (atom {})]
      (lifecycle/run-before-feature-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-feature-hooks!)))))

  (around [it]
    (binding [g/*state* (atom @g/*state*)]
      (lifecycle/run-before-scenario-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-scenario-hooks!)))))

  (it "episodes command is registered and has help"
    ;; Given an Isaac root at "isaac-state"  (episodes/migrate_session.feature:13)
    (g/with-step* "Given an Isaac root at \"isaac-state\"" "episodes/migrate_session.feature" 13 (fn [] (isaac.foundation.root-steps/in-memory-state "\"isaac-state\"")))
    ;; And the isaac EDN file "config/providers/grover.edn" exists with:  (episodes/migrate_session.feature:14)
    ;;   | path | value |  (episodes/migrate_session.feature:15)
    ;;   | api | grover |  (episodes/migrate_session.feature:16)
    ;;   | auth | none |  (episodes/migrate_session.feature:17)
    (g/with-step* "And the isaac EDN file \"config/providers/grover.edn\" exists with:" "episodes/migrate_session.feature" 14 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/providers/grover.edn" {:headers ["path" "value"], :rows [["api" "grover"] ["auth" "none"]], :header-line 15, :row-lines [16 17]})))
    ;; When isaac is run with "help episodes"  (episodes/migrate_session.feature:23)
    (g/with-step* "When isaac is run with \"help episodes\"" "episodes/migrate_session.feature" 23 (fn [] (isaac.foundation.cli-steps/isaac-run "help episodes")))
    ;; Then the stdout matches:  (episodes/migrate_session.feature:24)
    ;;   | pattern |  (episodes/migrate_session.feature:25)
    ;;   | Usage: isaac episodes \[subcommand\] \[options\] |  (episodes/migrate_session.feature:26)
    ;;   | Subcommands: |  (episodes/migrate_session.feature:27)
    ;;   | migrate-session <session-id>\s+Materialize a session as a closed episode |  (episodes/migrate_session.feature:28)
    ;;   | close\s+Close open episodes now \(seal scenes\) |  (episodes/migrate_session.feature:29)
    ;;   | list\s+List a crew's episodes |  (episodes/migrate_session.feature:30)
    (g/with-step* "Then the stdout matches:" "episodes/migrate_session.feature" 24 (fn [] (isaac.foundation.cli-steps/stdout-matches {:headers ["pattern"], :rows [["Usage: isaac episodes \\[subcommand\\] \\[options\\]"] ["Subcommands:"] ["migrate-session <session-id>\\s+Materialize a session as a closed episode"] ["close\\s+Close open episodes now \\(seal scenes\\)"] ["list\\s+List a crew's episodes"]], :header-line 25, :row-lines [26 27 28 29 30]})))
    ;; And the exit code is 0  (episodes/migrate_session.feature:31)
    (g/with-step* "And the exit code is 0" "episodes/migrate_session.feature" 31 (fn [] (isaac.foundation.cli-steps/exit-code-is "0"))))

  (it "migrating a session materializes a closed episode"
    ;; Given an Isaac root at "isaac-state"  (episodes/migrate_session.feature:13)
    (g/with-step* "Given an Isaac root at \"isaac-state\"" "episodes/migrate_session.feature" 13 (fn [] (isaac.foundation.root-steps/in-memory-state "\"isaac-state\"")))
    ;; And the isaac EDN file "config/providers/grover.edn" exists with:  (episodes/migrate_session.feature:14)
    ;;   | path | value |  (episodes/migrate_session.feature:15)
    ;;   | api | grover |  (episodes/migrate_session.feature:16)
    ;;   | auth | none |  (episodes/migrate_session.feature:17)
    (g/with-step* "And the isaac EDN file \"config/providers/grover.edn\" exists with:" "episodes/migrate_session.feature" 14 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/providers/grover.edn" {:headers ["path" "value"], :rows [["api" "grover"] ["auth" "none"]], :header-line 15, :row-lines [16 17]})))
    ;; Given the isaac EDN file "config/models/gist.edn" exists with:  (episodes/migrate_session.feature:36)
    ;;   | path | value |  (episodes/migrate_session.feature:37)
    ;;   | model | gist |  (episodes/migrate_session.feature:38)
    ;;   | provider | grover |  (episodes/migrate_session.feature:39)
    (g/with-step* "Given the isaac EDN file \"config/models/gist.edn\" exists with:" "episodes/migrate_session.feature" 36 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/gist.edn" {:headers ["path" "value"], :rows [["model" "gist"] ["provider" "grover"]], :header-line 37, :row-lines [38 39]})))
    ;; And config file "isaac.edn" containing:  (episodes/migrate_session.feature:40)
    (g/with-step* "And config file \"isaac.edn\" containing:" "episodes/migrate_session.feature" 40 (fn [] (isaac.config.config-steps/config-file-containing "isaac.edn" "{:episodes {:gist-model :gist}}")))
    ;; And the following sessions exist:  (episodes/migrate_session.feature:44)
    ;;   | name | crew |  (episodes/migrate_session.feature:45)
    ;;   | quiet-regatta | cordelia |  (episodes/migrate_session.feature:46)
    (g/with-step* "And the following sessions exist:" "episodes/migrate_session.feature" 44 (fn [] (isaac.session.session-steps/sessions-exist {:headers ["name" "crew"], :rows [["quiet-regatta" "cordelia"]], :header-line 45, :row-lines [46]})))
    ;; And session "quiet-regatta" has transcript:  (episodes/migrate_session.feature:47)
    ;;   | type | message.role | message.content |  (episodes/migrate_session.feature:48)
    ;;   | message | user | What wine pairs with roast pheasant? |  (episodes/migrate_session.feature:49)
    ;;   | message | assistant | A light pinot noir. |  (episodes/migrate_session.feature:50)
    ;;   | message | user | Now, about the regatta schedule. |  (episodes/migrate_session.feature:51)
    ;;   | message | assistant | The first race is Saturday at dawn. |  (episodes/migrate_session.feature:52)
    (g/with-step* "And session \"quiet-regatta\" has transcript:" "episodes/migrate_session.feature" 47 (fn [] (isaac.session.session-steps/session-has-transcript "quiet-regatta" {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "What wine pairs with roast pheasant?"] ["message" "assistant" "A light pinot noir."] ["message" "user" "Now, about the regatta schedule."] ["message" "assistant" "The first race is Saturday at dawn."]], :header-line 48, :row-lines [49 50 51 52]})))
    ;; And the following model responses are queued:  (episodes/migrate_session.feature:53)
    ;;   | model | type | content |  (episodes/migrate_session.feature:54)
    ;;   | gist | text | 1-2: Wine pairing for pheasant\n3-4: Regatta scheduling |  (episodes/migrate_session.feature:55)
