    ;; When isaac is run with "episodes migrate-session quiet-regatta"  (episodes/migrate_session.feature:56)
    (g/with-step* "When isaac is run with \"episodes migrate-session quiet-regatta\"" "episodes/migrate_session.feature" 56 (fn [] (isaac.foundation.cli-steps/isaac-run "episodes migrate-session quiet-regatta")))
    ;; Then the exit code is 0  (episodes/migrate_session.feature:57)
    (g/with-step* "Then the exit code is 0" "episodes/migrate_session.feature" 57 (fn [] (isaac.foundation.cli-steps/exit-code-is "0")))
    ;; And the stdout matches:  (episodes/migrate_session.feature:58)
    ;;   | pattern |  (episodes/migrate_session.feature:59)
    ;;   | migrating quiet-regatta -> episode |  (episodes/migrate_session.feature:60)
    ;;   | crew cordelia, 1 span, 4 messages |  (episodes/migrate_session.feature:61)
    ;;   | span 1/1: 4 messages -> 2 scenes \(\d+\.\ds, 25 in, 12 out\) |  (episodes/migrate_session.feature:62)
    ;;   | \s+1-2: Wine pairing for pheasant |  (episodes/migrate_session.feature:63)
    ;;   | \s+3-4: Regatta scheduling |  (episodes/migrate_session.feature:64)
    ;;   | migrated: 1 span, 2 scenes \(\d+\.\ds, 25 in, 12 out\) |  (episodes/migrate_session.feature:65)
    (g/with-step* "And the stdout matches:" "episodes/migrate_session.feature" 58 (fn [] (isaac.foundation.cli-steps/stdout-matches {:headers ["pattern"], :rows [["migrating quiet-regatta -> episode"] ["crew cordelia, 1 span, 4 messages"] ["span 1/1: 4 messages -> 2 scenes \\(\\d+\\.\\ds, 25 in, 12 out\\)"] ["\\s+1-2: Wine pairing for pheasant"] ["\\s+3-4: Regatta scheduling"] ["migrated: 1 span, 2 scenes \\(\\d+\\.\\ds, 25 in, 12 out\\)"]], :header-line 59, :row-lines [60 61 62 63 64 65]})))
    ;; And an episode exists for crew "cordelia" matching:  (episodes/migrate_session.feature:66)
    ;;   | key | value |  (episodes/migrate_session.feature:67)
    ;;   | id | #"\d{17}" |  (episodes/migrate_session.feature:68)
    ;;   | migrated-from | quiet-regatta |  (episodes/migrate_session.feature:69)
    (g/with-step* "And an episode exists for crew \"cordelia\" matching:" "episodes/migrate_session.feature" 66 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["id" "#\"\\d{17}\""] ["migrated-from" "quiet-regatta"]], :header-line 67, :row-lines [68 69]})))
    ;; And that episode has scenes matching:  (episodes/migrate_session.feature:70)
    ;;   | gist | text |  (episodes/migrate_session.feature:71)
    ;;   | Wine pairing for pheasant | #"(?s)pinot noir" |  (episodes/migrate_session.feature:72)
    ;;   | Regatta scheduling | #"(?s)race is Saturday" |  (episodes/migrate_session.feature:73)
    (g/with-step* "And that episode has scenes matching:" "episodes/migrate_session.feature" 70 (fn [] (isaac.episodes.episode-steps/that-episode-has-scenes-matching {:headers ["gist" "text"], :rows [["Wine pairing for pheasant" "#\"(?s)pinot noir\""] ["Regatta scheduling" "#\"(?s)race is Saturday\""]], :header-line 71, :row-lines [72 73]}))))

  (it "noisy preamble and fences around boundary lines still parse"
    ;; Given an Isaac root at "isaac-state"  (episodes/migrate_session.feature:13)
    (g/with-step* "Given an Isaac root at \"isaac-state\"" "episodes/migrate_session.feature" 13 (fn [] (isaac.foundation.root-steps/in-memory-state "\"isaac-state\"")))
    ;; And the isaac EDN file "config/providers/grover.edn" exists with:  (episodes/migrate_session.feature:14)
    ;;   | path | value |  (episodes/migrate_session.feature:15)
    ;;   | api | grover |  (episodes/migrate_session.feature:16)
    ;;   | auth | none |  (episodes/migrate_session.feature:17)
    (g/with-step* "And the isaac EDN file \"config/providers/grover.edn\" exists with:" "episodes/migrate_session.feature" 14 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/providers/grover.edn" {:headers ["path" "value"], :rows [["api" "grover"] ["auth" "none"]], :header-line 15, :row-lines [16 17]})))
