    ;;   | provider | grover |  (episodes/migrate_session.feature:79)
    (g/with-step* "Given the isaac EDN file \"config/models/gist.edn\" exists with:" "episodes/migrate_session.feature" 76 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/gist.edn" {:headers ["path" "value"], :rows [["model" "gist"] ["provider" "grover"]], :header-line 77, :row-lines [78 79]})))
