    (g/with-step* "And session \"chatty-model\" has transcript:" "episodes/migrate_session.feature" 87 (fn [] (isaac.session.session-steps/session-has-transcript "chatty-model" {:headers ["type" "message.role" "message.content"], :rows [["message" "user" "What wine pairs with roast pheasant?"] ["message" "assistant" "A light pinot noir."] ["message" "user" "Now, about the regatta schedule."] ["message" "assistant" "The first race is Saturday at dawn."]], :header-line 88, :row-lines [89 90 91 92]})))
    ;; And the following model responses are queued:  (episodes/migrate_session.feature:93)
    ;;   | model | type | content |  (episodes/migrate_session.feature:94)
