    (g/with-step* "And the following model responses are queued:" "episodes/migrate_session.feature" 93 (fn [] (isaac.session.session-steps/responses-queued {:headers ["model" "type" "content"], :rows [["gist" "text" "Sure — here are the scenes:\\n```\\n1-2: Wine pairing for pheasant\\n\\n3-4: Regatta scheduling\\n```\\nHope that helps!"]], :header-line 94, :row-lines [95]})))
    ;; When isaac is run with "episodes migrate-session chatty-model"  (episodes/migrate_session.feature:96)
