    ;;   | Regatta scheduling | #"(?s)race is Saturday" |  (episodes/migrate_session.feature:104)
    (g/with-step* "And that episode has scenes matching:" "episodes/migrate_session.feature" 101 (fn [] (isaac.episodes.episode-steps/that-episode-has-scenes-matching {:headers ["gist" "text"], :rows [["Wine pairing for pheasant" "#\"(?s)pinot noir\""] ["Regatta scheduling" "#\"(?s)race is Saturday\""]], :header-line 102, :row-lines [103 104]}))))

  (it "scene text is distilled — tool markers kept, payloads dropped"
    ;; Given an Isaac root at "isaac-state"  (episodes/migrate_session.feature:13)
    (g/with-step* "Given an Isaac root at \"isaac-state\"" "episodes/migrate_session.feature" 13 (fn [] (isaac.foundation.root-steps/in-memory-state "\"isaac-state\"")))
    ;; And the isaac EDN file "config/providers/grover.edn" exists with:  (episodes/migrate_session.feature:14)
    ;;   | path | value |  (episodes/migrate_session.feature:15)
    ;;   | api | grover |  (episodes/migrate_session.feature:16)
    ;;   | auth | none |  (episodes/migrate_session.feature:17)
    (g/with-step* "And the isaac EDN file \"config/providers/grover.edn\" exists with:" "episodes/migrate_session.feature" 14 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/providers/grover.edn" {:headers ["path" "value"], :rows [["api" "grover"] ["auth" "none"]], :header-line 15, :row-lines [16 17]})))
    ;; Given the isaac EDN file "config/models/gist.edn" exists with:  (episodes/migrate_session.feature:107)
    ;;   | path | value |  (episodes/migrate_session.feature:108)
    ;;   | model | gist |  (episodes/migrate_session.feature:109)
    ;;   | provider | grover |  (episodes/migrate_session.feature:110)
    (g/with-step* "Given the isaac EDN file \"config/models/gist.edn\" exists with:" "episodes/migrate_session.feature" 107 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/gist.edn" {:headers ["path" "value"], :rows [["model" "gist"] ["provider" "grover"]], :header-line 108, :row-lines [109 110]})))
    ;; And config file "isaac.edn" containing:  (episodes/migrate_session.feature:111)
    (g/with-step* "And config file \"isaac.edn\" containing:" "episodes/migrate_session.feature" 111 (fn [] (isaac.config.config-steps/config-file-containing "isaac.edn" "{:episodes {:gist-model :gist}}")))
    ;; And the following sessions exist:  (episodes/migrate_session.feature:115)
    ;;   | name | crew |  (episodes/migrate_session.feature:116)
    ;;   | tidy-larder | cordelia |  (episodes/migrate_session.feature:117)
