    ;; And session "tidy-larder" has transcript:  (episodes/migrate_session.feature:118)
    ;;   | type | message.role | message.toolCallId | message.content |  (episodes/migrate_session.feature:119)
    ;;   | message | user |  | What is in the fridge? |  (episodes/migrate_session.feature:120)
    ;;   | message | assistant |  | [{"type":"toolCall","id":"call_1","name":"fs__read","arguments":{"filePath":"fridge.txt"}}] |  (episodes/migrate_session.feature:121)
    ;;   | message | toolResult | call_1 | 1 sad lemon, mass of unidentified cheese, Hieronymus's emergency lettuce (DO NOT TOUCH) |  (episodes/migrate_session.feature:122)
    ;;   | message | assistant |  | One sad lemon and some cheese. Leave the lettuce alone. |  (episodes/migrate_session.feature:123)
    (g/with-step* "And session \"tidy-larder\" has transcript:" "episodes/migrate_session.feature" 118 (fn [] (isaac.session.session-steps/session-has-transcript "tidy-larder" {:headers ["type" "message.role" "message.toolCallId" "message.content"], :rows [["message" "user" "" "What is in the fridge?"] ["message" "assistant" "" "[{\"type\":\"toolCall\",\"id\":\"call_1\",\"name\":\"fs__read\",\"arguments\":{\"filePath\":\"fridge.txt\"}}]"] ["message" "toolResult" "call_1" "1 sad lemon, mass of unidentified cheese, Hieronymus's emergency lettuce (DO NOT TOUCH)"] ["message" "assistant" "" "One sad lemon and some cheese. Leave the lettuce alone."]], :header-line 119, :row-lines [120 121 122 123]})))
    ;; And the following model responses are queued:  (episodes/migrate_session.feature:124)
